 roles:stage('Обсудите подход и отход','Распределите управление, наблюдение и работу с концами до начала захода.','Сохраните свободный путь отхода и безопасные обязанности экипажа.',{roles:['План экипажа','Алекс управляет рулём. Сэм сообщает расстояния и следит за путём отхода. Джо по команде работает с подготовленными концами из безопасного положения.'],escape:['Путь отхода','До финального подхода слева доступен проход со свободной водой. В этом упражнении касание причала не требуется.']},{observer:['Задача Сэма',{watch:'Сообщать расстояния и следить за путём отхода',jump:'Прыгнуть на причал',push:'Оттолкнуть яхту руками'}],escape:['Запишите путь отмены подхода',{port:'Свободная вода слева до финального подхода',blocked:'Занятое место у причала',none:'Путь отхода не нужен'}]}),
